/bin/bash -lc "python3 - <<'PY'
import urllib.parse, urllib.request, json, time, re, os
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
# Get all GSE records matching mouse scRNA-seq H5/HDF5
params={'db':'gds','term':'scRNA-seq[All Fields] AND \"Mus musculus\"[Organism] AND (\"h5ad\"[Supplementary File Type] OR \"HDF5\"[Supplementary File Type])','retmax':'1000','retmode':'json'}
with urllib.request.urlopen(base+'esearch.fcgi?'+urllib.parse.urlencode(params),timeout=30) as r: ids=json.load(r)['esearchresult']['idlist']
records=[]
for i in range(0,len(ids),100):
    params={'db':'gds','id':','.join(ids[i:i+100]),'retmode':'json'}
    with urllib.request.urlopen(base+'esummary.fcgi?'+urllib.parse.urlencode(params),timeout=60) as r: s=json.load(r)
    res=s['result']
    for uid in res['uids']:
        d=res[uid]
        if d.get('entrytype')=='GSE': records.append(d)
    time.sleep(0.3)
print('GSE records',len(records))
rows=[]
for d in records:
    acc=d['accession']; num=acc[3:]
    url=f'https://ftp.ncbi.nlm.nih.gov/geo/series/{acc[:-3]}nnn/{acc}/suppl/filelist.txt'
    try:
        req=urllib.request.Request(url,headers={'User-Agent':'codex'})
        with urllib.request.urlopen(req,timeout=15) as r: text=r.read().decode('utf-8','replace')
        for line in text.splitlines():
            parts=line.split('\\t')
            if len(parts)>=4:
                name=parts[1]; size=parts[3]
                if any(x in name.lower() for x in ['.h5ad','.h5']):
                    rows.append((acc, name, size, d.get('n_samples'), (d.get('title') or '')[:80]))
    except Exception as e:
        pass
    time.sleep(0.08)
print('file rows',len(rows))
for r in rows:
    try: sz=int(r[2])
    except: sz=0
    if 100_000_000 <= sz <= 800_000_000:
        print(r[0], r[3], sz, r[1], r[4])
# also print all .h5ad sizes sorted by closeness to 152823896
print('\\nAll h5ad/h5 rows sorted by size diff')
arr=[]
for r in rows:
    try: sz=int(r[2])
    except: continue
    arr.append((abs(sz-152823896), r))
arr.sort()
for diff,r in arr[:50]:
    print(diff, r[0], r[2], r[1], r[3], r[4])
PY"

