import urllib.parse, urllib.request, json, time, sys
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
term='scRNA-seq[All Fields] AND \"Mus musculus\"[Organism] AND (\"h5ad\"[Supplementary File Type] OR \"H5\"[Supplementary File Type] OR \"HDF5\"[Supplementary File Type])'
params={'db':'gds','term':term,'retmax':'5000','retmode':'json'}
for attempt in range(5):
 try:
  with urllib.request.urlopen(base+'esearch.fcgi?'+urllib.parse.urlencode(params),timeout=30) as r: data=json.load(r)
  break
 except Exception as e: print('retry search',e); time.sleep(2)
ids=data['esearchresult']['idlist']
print('ids',len(ids),flush=True)
rows=[]
for i in range(0,len(ids),100):
 chunk=ids[i:i+100]
 p={'db':'gds','id':','.join(chunk),'retmode':'json'}
 for attempt in range(5):
  try:
   with urllib.request.urlopen(base+'esummary.fcgi?'+urllib.parse.urlencode(p),timeout=60) as r: s=json.load(r)
   break
  except Exception as e: print('retry sum',i,e); time.sleep(2)
 res=s['result']
 for uid in res['uids']:
  d=res[uid]
  if d.get('entrytype')=='GSE':
   rows.append(d)
 time.sleep(0.25)
print('GSE rows',len(rows),flush=True)
for d in rows:
 rel=d.get('relations') or []
 reltxt=str(rel)
 if 'SuperSeries' in reltxt or 'SubSeries' in reltxt or rel:
  print(d.get('accession'),'| n=',d.get('n_samples'),'| supp=',d.get('suppfile'),'| rel=',rel,'| title=',d.get('title'))
