import urllib.request, time
accessions='''GSE153162 GSE161132 GSE152125 GSE146020 GSE189870 GSE227320 GSE312067 GSE328459 GSE326044 GSE292319 GSE270265 GSE169519 GSE246574 GSE245106 GSE245105 GSE245104 GSE168776 GSE163532 GSE200202 GSE314058 GSE314059 GSE314176 GSE276209 GSE298893 GSE298892 GSE156628 GSE154213 GSE135737 GSE172327 GSE192766 GSE193533 GSE224398 GSE244877 GSE290341 GSE306567 GSE306676 GSE309445 GSE316394 GSE317430 GSE327967 GSE333844 GSE289369 GSE289367 GSE297068'''.split()
