/bin/bash -lc "python3 - <<'PY'
import urllib.parse, urllib.request, json, time
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
queries=[
 'cochlea[All Fields] AND ATAC-seq[All Fields] AND \"Mus musculus\"[Organism] AND (Hertzano[Author] OR Milon[Author] OR Ament[Author])',
 'cochlea[All Fields] AND \"Age-related hearing impairment\"[All Fields]',
 'scRNA-seq[All Fields] AND ATAC-seq[All Fields] AND cochlea[All Fields] AND \"Mus musculus\"[Organism]',
]
for q in queries:
 print('\\nQUERY',q)
 params={'db':'gds','term':q,'retmax':'100','retmode':'json'}
 for attempt in range(3):
  try:
   with urllib.request.urlopen(base+'esearch.fcgi?'+urllib.parse.urlencode(params),timeout=30) as r: data=json.load(r)
   break
  except Exception as e: print('retry',e); time.sleep(2)
 res=data['esearchresult']; print('count',res['count'],'ids',res['idlist'])
 if res['idlist']:
  params2={'db':'gds','id':','.join(res['idlist'][:100]),'retmode':'json'}
  with urllib.request.urlopen(base+'esummary.fcgi?'+urllib.parse.urlencode(params2),timeout=60) as r: s=json.load(r)
  for uid in s['result']['uids']:
   d=s['result'][uid]
   if d.get('entrytype')=='GSE':
    print(d.get('accession'),'| n=',d.get('n_samples'),'| title=',d.get('title'),'| rel=',d.get('relations'),'| subset=',d.get('subsetinfo'))
 time.sleep(1)
PY"

